import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.modulus = 998244353

        def fInv(self, x):
            # Fermat's little theorem for modular inverse
            return pow(x, self.modulus - 2, self.modulus)

        def mult(self, a, b, inv_b=None):
            if inv_b is not None:
                return (a * inv_b) % self.modulus
            else:
                return (a * b) % self.modulus

        def add(self, a, b):
            return (a + b) % self.modulus

        def subtract(self, a, b):
            return (a - b) % self.modulus

        def ncr(self, n, r):
            if r > n or r < 0:
                return 0
            numerator = 1
            denominator = 1
            for i in range(r):
                numerator = (numerator * (n - i)) % self.modulus
                denominator = (denominator * (i + 1)) % self.modulus
            inv_denominator = self.fInv(denominator)
            return (numerator * inv_denominator) % self.modulus

        def smallInv(self, x):
            return self.fInv(x)

def main():
    input_line = sys.stdin.readline().strip()
    tokens = input_line.split()
    n = int(tokens[0])
    m = int(tokens[1])

    mod = NumberTheory.Mod998()
    mod.fInv(n + m)

    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = (p * (n - i)) % mod.modulus
        inv = mod.smallInv(n + m - i)
        p = (p * inv) % mod.modulus
        phaseSize = (phaseSize + p) % mod.modulus
        i += 1

    answer = 0
    for k in range(1, n + 1):
        ncr_value = mod.ncr(n, k)
        term = (ncr_value * (m + k)) % mod.modulus
        inv_k = mod.smallInv(k)
        term = (term * inv_k) % mod.modulus
        term = (term * phaseSize) % mod.modulus
        if k % 2 == 1:
            answer = (answer + term) % mod.modulus
        else:
            answer = (answer - term) % mod.modulus

    print(answer)

if __name__ == "__main__":
    main()

